SELECT (WITH debate_judgments(verdict_tag,defense_standing) AS (VALUES ('HELD','COLLAPSED'),('HELD','PROP-DEPENDENT')), debate_results(framework_verdict,defense_standing,created_at) AS (VALUES ('HELD','COLLAPSED',TIMESTAMPTZ '2026-10-22 03:00:00+00')) SELECT count(*) FROM debate_judgments WHERE verdict_tag='HELD' AND defense_standing='COLLAPSED') AS s1_i, (WITH debate_judgments(verdict_tag,defense_standing) AS (VALUES ('HELD','COLLAPSED'),('HELD','PROP-DEPENDENT')), debate_results(framework_verdict,defense_standing,created_at) AS (VALUES ('HELD','COLLAPSED',TIMESTAMPTZ '2026-10-22 03:00:00+00')) SELECT count(*) FROM debate_results WHERE framework_verdict='HELD' AND defense_standing='COLLAPSED' AND created_at < TIMESTAMPTZ '2026-10-22 02:00:00+00') AS s2_ii, (WITH debate_results(framework_verdict,defense_standing,created_at) AS (VALUES ('HELD','COLLAPSED',TIMESTAMPTZ '2026-10-20 00:00:00+00')) SELECT count(*) FROM debate_results WHERE framework_verdict='HELD' AND defense_standing='COLLAPSED' AND created_at < TIMESTAMPTZ '2026-10-22 02:00:00+00') AS s3_ii, (SELECT count(*) FROM debate_results WHERE framework_verdict='HELD' AND defense_standing='COLLAPSED' AND created_at < now()) AS s4_ii, (SELECT count(*) FROM debate_judgments WHERE verdict_tag='HELD' AND defense_standing='COLLAPSED') AS s4_i;